<script setup lang="ts">
import { computed, ref } from 'vue'
import type { MarineApp, TaskNode } from '../../marine/model'
import { serviceById } from '../../marine/model'
import type { RunState } from '../../marine/runner'
import type { SensorSnapshot } from '../../marine/sensors'
import { buildApplicationFlow } from '../../marine/application-flow'
import LayeredApplicationGraph from './LayeredApplicationGraph.vue'
const props=defineProps<{app:MarineApp;run:RunState;snapshot:SensorSnapshot;gateway:boolean;blocked:boolean;motors:any[];motorMode:string;emergencyStopped:boolean;notice:string}>()
const emit=defineEmits<{back:[];start:[];pause:[];stop:[];emergency:[];reset:[];motor:[node:TaskNode];motorStop:[node:TaskNode]}>()
const flow=computed(()=>buildApplicationFlow(props.app))
const labels:Record<string,string>={idle:'等待启动',running:'运行中',paused:'已暂停',completed:'已完成',failed:'执行异常',cancelled:'已停止',waiting:'等待执行'}
const allNodes=computed(()=>props.app.steps.flatMap(s=>s.nodes))
const completed=computed(()=>Object.values(props.run.nodes).filter(n=>n.status==='completed').length)
const percentage=computed(()=>Math.round(Object.values(props.run.nodes).reduce((s,n)=>s+n.progress,0)/Math.max(1,allNodes.value.length)*100))
const sensorPage=ref(0),logPage=ref(0),returnPage=ref(0)
const sourceLabel=(source:string)=>({demo:'演示数据',simulated:'模拟执行',live:'实时采集',real:'真实设备'}[source]||source||'等待返回')
function resultValue(id:string){const value=props.run.nodes[id]?.result.value;return value===''||value==null?'—':value}
const motorDraft=ref<TaskNode|null>(null)
const sensed=computed(()=>flow.value.sensors.map(s=>({key:s.key,...props.snapshot.values[s.key]})))
const sensors=computed(()=>sensed.value.slice(sensorPage.value*4,sensorPage.value*4+4))
const actions=computed(()=>allNodes.value.filter(n=>serviceById(n.serviceId).kind==='action'))
const resultNodes=computed(()=>allNodes.value.slice(returnPage.value*2,returnPage.value*2+2))
const events=computed(()=>[...props.run.events].reverse())
const logs=computed(()=>events.value.slice(logPage.value*3,logPage.value*3+3))
const online=computed(()=>sensed.value.filter(s=>s.online).length)
const running=computed(()=>['running','paused'].includes(props.run.status))
function nodeLabel(id:string){const state=props.run.nodes[id]?.status||'waiting';return props.run.status==='paused'&&state==='running'?'已暂停':labels[state]||state}
function exportLogs(){const blob=new Blob([JSON.stringify({app:props.app.name,appId:props.app.id,status:props.run.status,events:props.run.events,results:props.run.nodes},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=props.app.name+'-运行日志.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function motorFor(node:TaskNode){return props.motors.find(m=>m.executorId===node.motor?.executorId)}
</script>
<template>
 <section class="independent-app" aria-label="独立应用运行大屏">
  <header class="ia-header"><button class="ia-back" @click="emit('back')">‹ 返回应用中心</button><div class="ia-title"><i/><h1>{{app.name}}</h1><span>{{labels[run.status]}}</span></div><div class="ia-controls"><button v-if="!running" :disabled="blocked" @click="emit('start')">▶ 启动</button><button v-else :disabled="blocked" @click="emit('pause')">{{run.status==='paused'?'▶ 继续':'Ⅱ 暂停'}}</button><button :disabled="!running||blocked" @click="emit('stop')">■ 停止</button></div></header>
  <div class="ia-metrics"><div><span>服务执行进度</span><strong>{{percentage}}<small>%</small></strong><div class="ia-progress"><i :style="{width:percentage+'%'}"/></div></div><div><span>完成服务</span><strong>{{completed}}<small>/ {{allNodes.length}}</small></strong></div><div><span>任务阶段</span><strong>{{run.status==='idle'?'—':Math.min(run.stepIndex+1,app.steps.length)}}<small>/ {{app.steps.length}}</small></strong></div><div><span>执行用时</span><strong>{{run.elapsed.toFixed(1)}}<small>秒</small></strong></div><div><span>感知在线</span><strong>{{online}}<small>/ {{sensed.length}}</small></strong></div><div><span>调度连接</span><strong class="ia-word">{{blocked?'连接中断':gateway?'网关已连接':'离线 / 演示'}}</strong><small>仅显示当前应用</small></div></div>
  <main class="ia-main">
   <aside class="ia-left">
    <section class="ia-panel ia-sensors"><header><h2>感知数据</h2><small>{{snapshot.source==='live'?'实时采集':'演示数据'}}</small></header><article v-for="sensor in sensors" :key="sensor.key"><div><span>{{sensor.label}}</span><small :class="{online:sensor.online}">{{sensor.online?'在线':'离线'}}</small></div><strong>{{sensor.online?sensor.value:'—'}}<small>{{sensor.unit}}</small></strong></article><footer v-if="sensed.length>4"><button :disabled="sensorPage===0" @click="sensorPage--">‹</button><span>{{sensorPage+1}} / {{Math.ceil(sensed.length/4)}}</span><button :disabled="(sensorPage+1)*4>=sensed.length" @click="sensorPage++">›</button></footer></section>
    <section class="ia-panel ia-hardware"><header><h2>执行设备</h2><small>{{actions.some(n=>n.serviceId==='M01')?motorMode==='real'?'真实电机':'模拟电机':'模拟设备'}}</small></header><article v-for="node in actions" :key="node.id"><i :class="{live:run.nodes[node.id]?.status==='running'&&run.status==='running'}"/><div><strong>{{serviceById(node.serviceId).name}}</strong><small>{{node.serviceId==='M01'?motorFor(node)?.online?'设备在线':'设备离线 / 未确认':'模拟执行接口'}}</small></div><span>{{nodeLabel(node.id)}}</span><button v-if="node.motor" @click="motorDraft=JSON.parse(JSON.stringify(node))">参数</button></article><p v-if="!actions.length">本应用仅采集数据</p><button v-if="actions.some(n=>n.serviceId==='M01')" class="ia-danger" @click="emergencyStopped?emit('reset'):emit('emergency')">{{emergencyStopped?'复位急停':'执行器急停'}}</button></section>
   </aside>
<section class="ia-panel ia-topology"><header><h2>实时调用链路</h2><span><i :class="{live:!blocked&&['running','completed'].includes(run.status)}"/>{{blocked?'连接中断':['running','completed'].includes(run.status)?'链路循环展示':labels[run.status]}}</span></header><LayeredApplicationGraph :app="app" :run="blocked?{...run,status:'paused'}:run"/></section>
   <aside class="ia-right">
    <section class="ia-panel ia-stages"><header><h2>任务阶段</h2><small>{{app.steps.length}} 阶段</small></header><article v-for="(step,i) in app.steps" :key="step.id" :class="{current:run.stepIndex===i&&running}" :style="{flex:step.nodes.length>1?1.7:1}"><b>{{String(i+1).padStart(2,'0')}}</b><div><strong>{{step.nodes.map(n=>serviceById(n.serviceId).name).join(' / ')}}</strong><small>{{step.nodes.length>1?'并行 · 全部完成后推进':'顺序执行'}}</small></div></article></section>
<section class="ia-panel ia-returns"><header><h2>服务返回数据</h2><small>{{allNodes.length}} 项</small></header><article v-for="node in resultNodes" :key="node.id"><div><span>{{serviceById(node.serviceId).name}}</span><small>{{nodeLabel(node.id)}}</small></div><strong>{{resultValue(node.id)}} <small>{{run.nodes[node.id]?.result.unit}}</small></strong><p>{{sourceLabel(run.nodes[node.id]?.result.source||'')}} · {{run.nodes[node.id]?.result.metric||'尚无执行返回'}}</p><p :title="run.nodes[node.id]?.result.detail">{{run.nodes[node.id]?.result.detail}}</p></article><footer><button :disabled="returnPage===0" @click="returnPage--">‹</button><span>{{returnPage+1}} / {{Math.ceil(allNodes.length/2)}}</span><button :disabled="(returnPage+1)*2>=allNodes.length" @click="returnPage++">›</button></footer></section>
   </aside>
  </main>
  <section class="ia-panel ia-log"><header><h2>事件流与运行日志 <small>{{events.length}} 条</small></h2><div><button :disabled="logPage===0" @click="logPage--">较新</button><button :disabled="(logPage+1)*3>=events.length" @click="logPage++">较早</button><button @click="exportLogs">导出日志 ↓</button></div></header><div class="ia-log-body"><article v-for="(event,i) in logs" :key="i"><time>+{{event.time.toFixed(1)}}s</time><span :class="event.kind">{{event.kind==='error'?'异常':'事件'}}</span><p>{{event.message}}</p></article><p v-if="!logs.length" class="ia-empty">等待启动 · 启动后记录本应用的服务执行、阶段推进和停止事件</p></div></section>
  <div v-if="motorDraft?.motor" class="ia-modal"><section><header><h2>电机运行参数</h2><button @click="motorDraft=null">关闭</button></header><p>{{motorDraft.motor.executorId}} · {{motorFor(motorDraft)?.actualRpm ?? '—'}} rpm</p><label>目标转速 <input v-model.number="motorDraft.motor.speedRpm" type="number" min="1" max="500"/> rpm</label><label>旋转方向 <select v-model="motorDraft.motor.direction"><option value="forward">正转</option><option value="reverse">反转</option></select></label><footer><button :disabled="blocked||run.nodes[motorDraft.id]?.status!=='running'||motorDraft.motor.speedRpm<1||motorDraft.motor.speedRpm>500" @click="emit('motor',motorDraft)">下发参数</button><button :disabled="blocked||run.nodes[motorDraft.id]?.status!=='running'" @click="emit('motorStop',motorDraft)">停止电机</button></footer></section></div>
  <footer class="ia-footer"><span>{{notice||'数据上报 → 服务处理 → 应用决策 → 指令下发 → 状态反馈'}}</span><span>通风 / 报警 / 排水为模拟执行</span></footer>
 </section>
</template>
<style scoped>
.ia-modal{position:absolute;inset:0;z-index:5;background:#040d17cc;display:grid;place-items:center}.ia-modal>section{width:420px;padding:25px;background:#102738;border:1px solid #42677c;border-radius:12px}.ia-modal header,.ia-modal footer{display:flex;justify-content:space-between;align-items:center}.ia-modal h2{font-size:20px}.ia-modal p{color:#7195ac}.ia-modal label{display:flex;align-items:center;gap:12px;margin:20px 0}.ia-modal input,.ia-modal select{color:#b6dce7;background:#0b1d2a;border:1px solid #36576e;padding:8px;width:140px}

.independent-app{font-size:14px;line-height:1.4}.independent-app article{font-size:12px;line-height:1.4}.ia-stages{display:flex;flex-direction:column}.ia-stages article{flex:1;align-items:center;min-height:0}.ia-returns article>strong{display:block;line-height:1.25}.ia-hardware article{min-height:0;flex:1}.ia-stages strong{display:block}
.independent-app{position:fixed;inset:0;z-index:100;background:radial-gradient(ellipse at 53% 48%,#102b3b 0,#081725 58%,#060f1b 100%);color:#c7dce7;display:flex;flex-direction:column;padding:0 24px;font-family:'Microsoft YaHei',sans-serif;overflow:hidden}.independent-app *{box-sizing:border-box}.independent-app button{background:#132b3b;border:1px solid #2c4c61;border-radius:5px;color:#9dbdce;cursor:pointer;padding:7px 12px;font:inherit;font-size:12px}.independent-app button:hover{border-color:#6fa4b8}.independent-app button:disabled{opacity:.3;cursor:default}.ia-header{height:72px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #274357;flex-shrink:0;gap:20px}.ia-title{display:flex;align-items:center;gap:14px}.ia-title h1{font-size:25px;font-weight:500;letter-spacing:2px;margin:0;color:#d0e9ee}.ia-title>i{width:8px;height:8px;background:#73d2c8;transform:rotate(45deg);box-shadow:0 0 16px #74c7d1}.ia-title>span{font-size:12px;color:#7fbebc}.ia-controls{display:flex;gap:8px}.ia-metrics{display:grid;grid-template-columns:1.3fr repeat(4,1fr) 1.2fr;gap:30px;padding:18px 12px;flex-shrink:0}.ia-metrics>div{border-right:1px solid #1a3547;position:relative;display:flex;align-items:baseline;gap:14px;flex-wrap:wrap}.ia-metrics span{font-size:13px;color:#6e94a9}.ia-metrics strong{font-size:29px;font-weight:400;color:#b4dfe7;font-variant-numeric:tabular-nums}.ia-metrics small{font-size:12px;margin-left:5px;color:#678da2}.ia-metrics .ia-word{font-size:16px}.ia-progress{width:85%;height:2px;background:#203b4a;margin-top:0}.ia-progress i{display:block;height:100%;background:#68cbb9}.ia-main{flex:1;min-height:0;display:grid;grid-template-columns:260px minmax(0,1fr) 300px;gap:16px}.ia-left,.ia-right{display:flex;flex-direction:column;gap:14px;min-height:0}.ia-panel{border:1px solid #203c50;background:linear-gradient(125deg,#11283a88,#0a1926bb);border-radius:8px;min-height:0;padding:14px 16px;position:relative}.ia-panel:before{content:'';position:absolute;top:-1px;left:18px;width:34px;height:2px;background:#4d8eaa}.ia-panel header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.ia-panel h2{font-size:16px;font-weight:500;margin:0;letter-spacing:1px;color:#b7d4e2}.ia-panel header small{font-size:10px;font-weight:400;color:#63859c;letter-spacing:0}.ia-panel header>span{font-size:11px;color:#688d9f}.ia-panel footer{display:flex;justify-content:center;align-items:center;gap:15px;color:#68899e;font-size:11px;margin-top:auto}.ia-panel footer button{padding:1px 10px}.ia-sensors{flex:1.1;display:flex;flex-direction:column}.ia-sensors article{flex:1;border-bottom:1px solid #1c3547;padding:9px 0;min-height:0}.ia-sensors article>div,.ia-returns article>div{display:flex;justify-content:space-between;gap:8px;font-size:13px;color:#8caebf}.ia-sensors article small{font-size:10px;color:#5c7588}.ia-sensors article small.online{color:#66b7a3}.ia-sensors article>strong{font-size:29px;font-weight:400;line-height:1.4;color:#c6e3eb}.ia-sensors strong small{margin-left:6px;font-size:12px}.ia-hardware{flex:.8;display:flex;flex-direction:column}.ia-hardware article{display:flex;gap:9px;align-items:center;padding:12px 0;border-top:1px solid #20394b}.ia-hardware article>i,.ia-topology header i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#405b6a;margin-right:5px}.ia-hardware article>i.live,.ia-topology header i.live{background:#76c9ba;box-shadow:0 0 8px #5ccab8}.ia-hardware article>div{flex:1}.ia-hardware strong{font-size:13px;font-weight:400}.ia-hardware small{display:block;font-size:10px;color:#587b91;margin-top:5px}.ia-hardware article>span{font-size:10px;color:#6e9ba9}.ia-topology{display:flex;flex-direction:column;padding:14px 10px 3px}.ia-topology header{margin:0 10px;flex-shrink:0}.ia-topology :deep(.layered-graph){flex:1}.ia-stages{flex:1}.ia-stages article{display:flex;gap:12px;padding:13px 0;border-top:1px solid #20394c}.ia-stages b{color:#446d87;font-size:21px;font-weight:400}.ia-stages strong{font-size:12px;font-weight:400;line-height:1.7;color:#90aebe}.ia-stages small{display:block;color:#4f778e;font-size:10px;margin-top:4px}.ia-stages .current b,.ia-stages .current strong{color:#83cdbc}.ia-returns{flex:1;display:flex;flex-direction:column}.ia-returns article{flex:1;border-top:1px solid #20394c;padding:8px 0;min-height:0}.ia-returns article small{font-size:10px;color:#63879b}.ia-returns article>strong{font-size:17px;font-weight:400;color:#b4dce2}.ia-returns p{font-size:10px;color:#5e8297;margin:3px 0;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.ia-log{height:162px;flex-shrink:0;margin-top:14px;padding:12px 18px}.ia-log header{margin-bottom:8px}.ia-log header>div{display:flex;gap:7px}.ia-log header button{padding:3px 12px;font-size:11px}.ia-log-body article{display:flex;align-items:center;gap:20px;border-top:1px solid #1a3244;padding:7px 0;font-size:12px}.ia-log-body time{width:70px;color:#6492a9;font-variant-numeric:tabular-nums}.ia-log-body article>span{color:#71b2ad;font-size:10px;border:1px solid #2c5358;padding:1px 8px}.ia-log-body p{margin:0;color:#93b0c1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ia-empty{font-size:12px;color:#57778b!important;padding:20px 0}.ia-footer{height:29px;flex-shrink:0;display:flex;justify-content:space-between;align-items:center;font-size:10px;color:#53778c}.ia-danger{margin-top:auto;color:#df9985!important;border-color:#794d46!important}@media(max-height:850px){.ia-header{height:58px}.ia-title h1{font-size:21px}.ia-metrics{padding:12px 6px;gap:15px}.ia-metrics>div{gap:5px}.ia-metrics strong{font-size:23px}.ia-metrics span{font-size:11px}.ia-main{grid-template-columns:210px minmax(0,1fr) 240px;gap:10px}.ia-panel{padding:10px 12px}.ia-left,.ia-right{gap:10px}.ia-panel header{margin-bottom:5px}.ia-panel h2{font-size:14px}.ia-sensors article{padding:3px 0}.ia-sensors article>strong{font-size:22px}.ia-hardware article{padding:7px 0}.ia-stages article{padding:7px 0}.ia-stages strong{font-size:11px}.ia-stages small{margin-top:0}.ia-returns article{padding:3px 0}.ia-returns article>div{font-size:11px}.ia-returns p{-webkit-line-clamp:1}.ia-log{height:134px;margin-top:10px}.ia-log-body article{padding:4px 0}.ia-footer{height:24px}}
</style>
